export function PasswordReset({
  heading = "{{heading}}",
  stage = "{{stage}}",
  email = "{{email}}",
  showPassword = {{showPassword}},
  accent = "{{accent}}",
}) {
  const inputStyle = { width: "100%", boxSizing: "border-box", padding: "9px 10px", borderRadius: 8, border: "1.5px solid #24143030", font: "inherit" };
  const submitStyle = { width: "100%", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#14351f", fontWeight: 700, cursor: "pointer" };
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: 20, borderRadius: 14, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 16 }}>{heading}</h3>
      {stage === "Request" ? (
        <div>
          <p style={{ margin: "0 0 14px", fontSize: 13, color: "#24143099" }}>Enter your email and we’ll send a link to reset your password.</p>
          <label style={{ display: "block", marginBottom: 14 }}>
            <span style={{ display: "block", marginBottom: 5, fontWeight: 600, fontSize: 13 }}>Email</span>
            <input type="email" defaultValue={email} autoComplete="username" style={inputStyle} />
          </label>
          <button type="submit" style={submitStyle}>Send reset link</button>
        </div>
      ) : (
        <div>
          <p style={{ margin: "0 0 14px", fontSize: 13, color: "#24143099" }}>If an account exists for {email}, a reset link is on its way.</p>
          <label style={{ display: "block", marginBottom: 14 }}>
            <span style={{ display: "block", marginBottom: 5, fontWeight: 600, fontSize: 13 }}>New password</span>
            <div style={{ position: "relative" }}>
              <input type={showPassword ? "text" : "password"} autoComplete="new-password" style={{ ...inputStyle, paddingRight: 56 }} />
              <button type="button" aria-pressed={showPassword} aria-label="Show new password"
                style={{ position: "absolute", right: 6, top: "50%", transform: "translateY(-50%)", border: "none", background: "none", cursor: "pointer", color: "#241430", fontWeight: 700, fontSize: 12, padding: "4px 6px" }}>
                {showPassword ? "Hide" : "Show"}
              </button>
            </div>
          </label>
          <button type="submit" style={submitStyle}>Set new password</button>
        </div>
      )}
    </div>
  );
}
